const MODEL = JSON.parse(MODEL_JSON);
const VOCAB = MODEL.vocab;
const STOI = new Map(VOCAB.map((ch, i) => [ch, i]));
const D = MODEL.config.d_model;
const H = MODEL.config.n_head;
const HD = D / H;
const V = VOCAB.length;
const CTX = MODEL.config.ctx;
const NL = MODEL.config.n_layer;
const MLPW = MODEL.config.mlp_ratio * D;

function b64ToInt8(b64) {
  const bin = atob(b64);
  const out = new Int8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function dequantize(t) {
  const q = b64ToInt8(t.b64);
  const out = new Float32Array(q.length);
  for (let i = 0; i < q.length; i++) out[i] = q[i] * t.scale;
  return out;
}

const TENSOR_NAMES = Object.keys(MODEL.tensors);
const PRISTINE = {};
let PARAM_COUNT = 0;
for (const name of TENSOR_NAMES) {
  PRISTINE[name] = dequantize(MODEL.tensors[name]);
  PARAM_COUNT += PRISTINE[name].length;
}

function weightsHash(w) {
  let h = 0x811c9dc5;
  for (const name of TENSOR_NAMES) {
    const bytes = new Uint8Array(w[name].buffer, w[name].byteOffset, w[name].byteLength);
    for (let i = 0; i < bytes.length; i++) {
      h ^= bytes[i];
      h = Math.imul(h, 0x01000193);
    }
  }
  return (h >>> 0).toString(16).padStart(8, "0");
}

const PRISTINE_HASH = weightsHash(PRISTINE);

function layerNorm(x, T, w, b, out) {
  for (let t = 0; t < T; t++) {
    const o = t * D;
    let mean = 0;
    for (let i = 0; i < D; i++) mean += x[o + i];
    mean /= D;
    let v = 0;
    for (let i = 0; i < D; i++) {
      const d = x[o + i] - mean;
      v += d * d;
    }
    const inv = 1 / Math.sqrt(v / D + 1e-5);
    for (let i = 0; i < D; i++) out[o + i] = (x[o + i] - mean) * inv * w[i] + b[i];
  }
}

function linear(x, T, nin, nout, w, b, out) {
  for (let t = 0; t < T; t++) {
    const xo = t * nin;
    const yo = t * nout;
    for (let o = 0; o < nout; o++) {
      let s = b[o];
      const wo = o * nin;
      for (let i = 0; i < nin; i++) s += w[wo + i] * x[xo + i];
      out[yo + o] = s;
    }
  }
}

function gelu(x) {
  return 0.5 * x * (1 + Math.tanh(0.7978845608028654 * (x + 0.044715 * x * x * x)));
}

function attention(Wt, ln, T, layer, out, trace) {
  const qkv = new Float32Array(T * 3 * D);
  linear(ln, T, D, 3 * D, Wt[`h${layer}.attn.qkv.w`], Wt[`h${layer}.attn.qkv.b`], qkv);
  const ctxv = new Float32Array(T * D);
  const scale = 1 / Math.sqrt(HD);
  const attRows = trace ? [] : null;
  for (let h = 0; h < H; h++) {
    const qo = h * HD;
    const ko = D + h * HD;
    const vo = 2 * D + h * HD;
    for (let i = 0; i < T; i++) {
      const row = new Float64Array(i + 1);
      let max = -Infinity;
      for (let j = 0; j <= i; j++) {
        let s = 0;
        for (let d = 0; d < HD; d++) s += qkv[i * 3 * D + qo + d] * qkv[j * 3 * D + ko + d];
        s *= scale;
        row[j] = s;
        if (s > max) max = s;
      }
      let sum = 0;
      for (let j = 0; j <= i; j++) {
        row[j] = Math.exp(row[j] - max);
        sum += row[j];
      }
      for (let j = 0; j <= i; j++) row[j] /= sum;
      if (trace && i === T - 1) attRows[h] = Float32Array.from(row);
      for (let d = 0; d < HD; d++) {
        let s = 0;
        for (let j = 0; j <= i; j++) s += row[j] * qkv[j * 3 * D + vo + d];
        ctxv[i * D + h * HD + d] = s;
      }
    }
  }
  if (trace) trace.attn[layer] = attRows;
  linear(ctxv, T, D, D, Wt[`h${layer}.attn.proj.w`], Wt[`h${layer}.attn.proj.b`], out);
}

function forward(Wt, ids, trace) {
  const T = ids.length;
  const x = new Float32Array(T * D);
  for (let t = 0; t < T; t++) {
    const wo = ids[t] * D;
    const po = t * D;
    for (let i = 0; i < D; i++) x[po + i] = Wt.wte[wo + i] + Wt.wpe[po + i];
  }
  if (trace) {
    const last = ids[T - 1];
    trace.wteRow = Wt.wte.slice(last * D, last * D + D);
    trace.wpeRow = Wt.wpe.slice((T - 1) * D, T * D);
    trace.embed = x.slice((T - 1) * D, T * D);
  }
  const ln = new Float32Array(T * D);
  const tmp = new Float32Array(T * D);
  const hidden = new Float32Array(T * MLPW);
  for (let l = 0; l < NL; l++) {
    layerNorm(x, T, Wt[`h${l}.ln1.w`], Wt[`h${l}.ln1.b`], ln);
    attention(Wt, ln, T, l, tmp, trace);
    for (let i = 0; i < T * D; i++) x[i] += tmp[i];
    if (trace) trace.afterAttn[l] = x.slice((T - 1) * D, T * D);
    layerNorm(x, T, Wt[`h${l}.ln2.w`], Wt[`h${l}.ln2.b`], ln);
    linear(ln, T, D, MLPW, Wt[`h${l}.mlp.fc.w`], Wt[`h${l}.mlp.fc.b`], hidden);
    for (let i = 0; i < T * MLPW; i++) hidden[i] = gelu(hidden[i]);
    linear(hidden, T, MLPW, D, Wt[`h${l}.mlp.proj.w`], Wt[`h${l}.mlp.proj.b`], tmp);
    for (let i = 0; i < T * D; i++) x[i] += tmp[i];
    if (trace) trace.afterMlp[l] = x.slice((T - 1) * D, T * D);
  }
  layerNorm(x, T, Wt["lnf.w"], Wt["lnf.b"], ln);
  if (trace) trace.lnf = ln.slice((T - 1) * D, T * D);
  const logits = new Float32Array(T * V);
  for (let t = 0; t < T; t++) {
    const xo = t * D;
    for (let v = 0; v < V; v++) {
      let s = 0;
      const wo = v * D;
      for (let i = 0; i < D; i++) s += ln[xo + i] * Wt.wte[wo + i];
      logits[t * V + v] = s;
    }
  }
  return logits;
}

function argmaxRow(arr, off) {
  let best = off;
  for (let i = off + 1; i < off + V; i++) if (arr[i] > arr[best]) best = i;
  return best - off;
}

function softmaxRow(logits, off, temperature) {
  const t = Math.max(temperature, 1e-3);
  let max = -Infinity;
  for (let i = 0; i < V; i++) if (logits[off + i] / t > max) max = logits[off + i] / t;
  const out = new Float64Array(V);
  let sum = 0;
  for (let i = 0; i < V; i++) {
    out[i] = Math.exp(logits[off + i] / t - max);
    sum += out[i];
  }
  for (let i = 0; i < V; i++) out[i] /= sum;
  return out;
}

// mulberry32 so a given seed reproduces the same draws without touching Math.random
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function drawFrom(probs, rand) {
  const r = rand();
  let cum = 0;
  for (let i = 0; i < probs.length; i++) {
    cum += probs[i];
    if (r <= cum) return i;
  }
  return probs.length - 1;
}

function pickNext(Wt, ids, { greedy, temperature, rand }) {
  const win = ids.slice(-CTX);
  const logits = forward(Wt, win);
  const off = (win.length - 1) * V;
  if (greedy) return argmaxRow(logits, off);
  return drawFrom(softmaxRow(logits, off, temperature), rand);
}

function generateTokens(Wt, promptIds, n, { greedy, temperature, seed }) {
  const ids = [...promptIds];
  const out = [];
  const rand = greedy ? null : mulberry32(seed);
  for (let k = 0; k < n; k++) {
    const next = pickNext(Wt, ids, { greedy, temperature, rand });
    ids.push(next);
    out.push(next);
  }
  return out;
}

const CHAR_FIXES = {
  "‘": "'",
  "’": "'",
  "“": "'",
  "”": "'",
  "—": "-",
  "–": "-",
  "\t": " ",
};

function encodePrompt(text) {
  const ids = [];
  const dropped = new Set();
  for (const ch of text) {
    let c = ch;
    if (!STOI.has(c) && c in CHAR_FIXES) c = CHAR_FIXES[c];
    if (STOI.has(c)) ids.push(STOI.get(c));
    else dropped.add(ch);
  }
  return { ids, dropped: [...dropped] };
}

function decodeIds(ids) {
  let s = "";
  for (const id of ids) s += VOCAB[id];
  return s;
}

export const engine = {
  MODEL,
  VOCAB,
  CTX,
  V,
  PRISTINE,
  forward,
  generateTokens,
  encodePrompt,
};

